class Sigmet(Sigmettype):
    """
    A SIGMET (significant meteorological) report.

    SIGMETs report the occurrence and/or expected occurrence of specified en-route weather phenomena which may
    affect the safety of aircraft operations, and of the development of those phenomena over time. The SIGMET report
    class represents the base SIGMET types that may be reported such as squall lines, thunderstorms, dust storms,
    turbulence, etc. Tropical cyclone and volcanic ash SIGMET reports are subclasses of SIGMET due to their ability
    to report additional information, including volcano/tropical cyclone identification and forecast position(s).
    SIGMETs may report either observed or forecast hazardous conditions. Additionally, a forecast position may be
    reported.
    """

    class Meta:
        name = "SIGMET"
        namespace = "http://icao.int/iwxxm/2025-2"

    model_config = ConfigDict(defer_build=True)


